import {STM32_BOARDS} from './stm32-boards.js';
import {blankPinConfig,pinFunctions,generatePinSources,normalizePinConfig} from './stm32-pin-config.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showSTMPins(project,board,{showDialog,apply}){
 const isPlanned=(pin,fn)=>pinFunctions(board,pin).find(f=>f.id===fn)?.status==='planned';const b=STM32_BOARDS[board];if(!b)throw Error('STM32 projesi gerekli.');let draft=normalizePinConfig(project.settings.stm32Pins||blankPinConfig(),board),selected=b.gpio[0];const $=id=>document.getElementById(id),pins=[...new Set(b.pins.map(p=>p.net).filter(p=>/^P[A-H]\d+$/.test(p)))].sort((a,c)=>a[1].localeCompare(c[1])||+a.slice(2)-+c.slice(2));
 showDialog('STM32 · Pin ve çevrebirim yapılandırması',`<div class="stm-config"><div class="stm-config-head"><div><strong>${esc(b.name)}</strong><p>${b.hz/1e6} MHz · ${b.flashSize/1024} KiB Flash · ${b.ram/1024} KiB SRAM</p></div><span>${project.language==='cpp'?'Bu projeye özel · C++17':'Bu projeye özel · C17'}</span></div><div class="stm-config-grid"><aside><div class="stm-pinmap" style="aspect-ratio:${b.width}/${b.height}"><img src="./assets/${b.asset}" alt="${esc(b.name)} pin haritası">${b.pins.filter(p=>/^P[A-H]\d+$/.test(p.net)).map(p=>`<button class="stm-pad ${b.gpio.includes(p.net)?'':'reserved'}" data-stm-pin="${p.net}" style="left:${p.x/b.width*100}%;top:${p.y/b.height*100}%" title="${esc(p.id+' · '+p.net)}" aria-label="${esc(p.id+' · '+p.net+' pinini seç')}"></button>`).join('')}</div><p class="stm-map-legend"><i></i> GPIO / bus / USART1 / ADC / PWM / SPI1 / I²C1 <i class="planned"></i> Datasheet planı <i class="reserved"></i> Kartta ayrılmış</p><p class="support-note">${esc(b.reserved)}</p><a href="${esc(b.source)}" target="_blank" rel="noopener">ST datasheet / başlık ↗</a>${b.boardSource?`<br><a href="${esc(b.boardSource)}" target="_blank" rel="noopener">Üretici devre şeması ↗</a>`:''}</aside><section><label>Pin ara<input id="stm-pin-search" placeholder="PA0, PB7, SPI…"></label><div class="stm-pin-list" id="stm-pin-list"></div></section><section class="stm-pin-editor"><h3 id="stm-pin-title"></h3><p id="stm-pin-aliases"></p><label>Pin görevi<select id="stm-pin-function"></select></label><label>C etiketi<input id="stm-pin-label" maxlength="24" placeholder="LED, BUTTON, CS"></label><label>Başlangıç çıkış seviyesi<select id="stm-pin-initial"><option value="0">LOW · 0</option><option value="1">HIGH · 1</option></select></label><label>EXTI giriş pull<select id="stm-exti-pull"><option value="0">Floating</option><option value="1">Pull-up</option><option value="2">Pull-down</option></select></label><div id="stm-pwm-fields" hidden><label>Timer PWM frekansı (Hz)<input id="stm-pwm-hz" type="number" min="1" max="20000" value="1000"></label><label>PWM duty (%)<input id="stm-pwm-duty" type="number" min="0" max="100" value="0"></label></div><div id="stm-capture-fields" hidden><label>TIM2 yakalama kenarı<select id="stm-capture-edge"><option value="0">Yükselen</option><option value="1">Düşen</option>${b.cpu==='cortex-m4f'?'<option value="2">İki kenar</option>':''}</select></label><label>Yakalama giriş bölücüsü<select id="stm-capture-divider">${[1,2,4,8].map(n=>`<option value="${n}">/${n}</option>`).join('')}</select></label><label>TIM2 sayaç isteği (Hz)<input id="stm-capture-hz" type="number" min="${Math.ceil(b.hz/65536)}" max="1000000" value="1000000"></label><p class="support-note">Doğrudan TI girişi · filtresiz. CCR ve IRQ28 gerçek pin kenarlarını izler. TIM2 capture kanalları aynı sayaç hızını paylaşır.</p></div><p id="stm-pin-support" role="status"></p><hr><label><input id="stm-boot0" type="checkbox" ${draft.boot0?'checked':''}> BOOT0 jumper HIGH</label><label><input id="stm-boot1" type="checkbox" ${draft.boot1?'checked':''}> BOOT1 jumper HIGH</label><p class="support-note">Reset anında seçilir: BOOT0 LOW → Flash; HIGH + BOOT1 LOW → USART bootloader; ikisi HIGH → SRAM. Başlıkta BOOT0/PB2 bağlantısı varsa fiziksel seviye geçerlidir. NRST pini haricî aktif LOW reset girişidir.</p><hr><label>Dahili sensör sıcaklığı (°C)<input id="stm-internal-temperature" type="number" min="-40" max="125" step="0.1" value="${draft.internalTemperature}"></label><label>VBAT modeli (V)<input id="stm-internal-vbat" type="number" min="0" max="3.6" step="0.1" value="${draft.internalVBAT}"></label><p class="support-note">Nominal ADC modeli · VDDA 3.3 V. Fabrika kalibrasyonu ve termal güç modeli içermez.</p><hr><label>RTC başlangıcı<select id="stm-rtc-source">${[[0,'Kapalı / main.c yönetir'],[1,'LSE · 32.768 kHz'],[2,'LSI · nominal iç saat'],[3,'HSE bölücüsü']].map(([n,t])=>`<option value="${n}" ${draft.rtcSource===n?'selected':''}>${t}</option>`).join('')}</select></label><p class="support-note">RTC 1 Hz başlangıcı; backup kayıtlarını silmez. F103 sayaç, F401/F411 takvim modelidir. Kaynak değişimi backup domain reset gerektirir. Saatler sanal nominal kaynaklardır.</p><label><input id="stm-uart-on" type="checkbox" ${draft.uart.enabled?'checked':''}> Seri terminali başlat</label><label>Terminal baud<select id="stm-uart-baud">${[9600,19200,38400,57600,115200].map(n=>`<option ${draft.uart.baud===n?'selected':''}>${n}</option>`).join('')}</select></label><label>USART1 fiziksel baud<select id="stm-usart1-baud">${[9600,19200,38400,57600,115200].map(n=>`<option ${draft.usart1Baud===n?'selected':''}>${n}</option>`).join('')}</select></label>${[1,2].map(n=>`<label>USART${n} oversampling<select id="stm-u${n}-sampling"><option value="16">16×</option>${b.cpu==='cortex-m4f'?'<option value="8">8×</option>':''}</select></label><label>USART${n} veri bitleri<select id="stm-u${n}-bits">${[7,8,9].map(v=>`<option ${draft['usart'+n+'Bits']===v?'selected':''}>${v}</option>`).join('')}</select></label><label>USART${n} parity<select id="stm-u${n}-parity">${['Yok','Even','Odd'].map((v,i)=>`<option value="${i}" ${draft['usart'+n+'Parity']===i?'selected':''}>${v}</option>`).join('')}</select></label><label>USART${n} stop bitleri<select id="stm-u${n}-stops">${[.5,1,1.5,2].map(v=>`<option ${draft['usart'+n+'Stops']===v?'selected':''}>${v}</option>`).join('')}</select></label>${n===2?`<label>USART2 fiziksel baud<select id="stm-u2-baud">${[9600,19200,38400,57600,115200].map(v=>`<option ${draft.usart2Baud===v?'selected':''}>${v}</option>`).join('')}</select></label>`:''}`).join('')}<p class="support-note">7-bit için parity gerekir; 9-bit için parity yoktur. USART2 PA2/PA3 fiziksel hatları Blue Pill/WeAct kartlarında seçilir. Nucleo C04 başlıkları SB62/63 OFF profilinde kapalıdır; VCP byte terminali korunur.</p><p class="support-note">${b.terminalNumber===2?'USART1 fiziksel başlık, USART2 ayrı ST-LINK VCP terminalidir.':'Kartın fiziksel USART1 ile terminal aynı birimdir; fiziksel baud geçerlidir. RX verisi bağlı cihazdan alınır.'}</p><label>Yazılım I²C hızı<select id="stm-i2c-hz">${[1000,5000,10000].map(n=>`<option value="${n}" ${draft.i2cHz===n?'selected':''}>${n/1000} kHz</option>`).join('')}</select></label><label>Yazılım SPI hızı<select id="stm-spi-hz">${[10000,20000].map(n=>`<option value="${n}" ${draft.spiHz===n?'selected':''}>${n/1000} kHz</option>`).join('')}</select></label><label>Donanım SPI1 saat isteği<select id="stm-hw-spi-hz">${[500000,1000000].map(n=>`<option value="${n}" ${draft.hwSpi1Hz===n?'selected':''}>${n/1000} kHz</option>`).join('')}</select></label><label>SPI1 saat modu<select id="stm-hw-spi-mode">${[0,1,2,3].map(n=>`<option value="${n}" ${draft.hwSpi1Mode===n?'selected':''}>Mode ${n} · CPOL ${n>>1} / CPHA ${n&1}</option>`).join('')}</select></label><label>SPI1 veri çerçevesi<select id="stm-hw-spi-bits">${[8,16].map(n=>`<option ${draft.hwSpi1Bits===n?'selected':''}>${n}</option>`).join('')}</select></label><label>SPI1 bit sırası<select id="stm-hw-spi-order"><option value="0" ${!draft.hwSpi1Lsb?'selected':''}>MSB-first</option><option value="1" ${draft.hwSpi1Lsb?'selected':''}>LSB-first</option></select></label><label>Donanım I²C1 hızı<select id="stm-hw-i2c-hz">${[10000,50000,100000,400000].map(n=>`<option value="${n}" ${draft.hwI2c1Hz===n?'selected':''}>${n/1000} kHz</option>`).join('')}</select></label><p class="support-note">I²C1 · 7-bit master · açık drenaj · pull-up gereklidir. ACK/POS ve STOP gerçek registerlerle çalışır.</p><p id="stm-spi-clock" class="support-note"></p><hr><label>TIM2 encoder sayım modu<select id="stm-encoder-mode">${[[1,'TI2 / B · 2 kenar'],[2,'TI1 / A · 2 kenar'],[3,'TI1 + TI2 · 4 kenar']].map(([n,t])=>`<option value="${n}" ${draft.encoderMode===n?'selected':''}>${t}</option>`).join('')}</select></label><label>Encoder sayaç üst sınırı<input id="stm-encoder-arr" type="number" min="1" max="${b.cpu==='cortex-m4f'?4294967295:65535}" value="${draft.encoderARR}"></label><label>Encoder giriş tersleme<select id="stm-encoder-invert">${[[0,'Normal'],[1,'A ters'],[2,'B ters'],[3,'A + B ters']].map(([n,t])=>`<option value="${n}" ${draft.encoderInvert===n?'selected':''}>${t}</option>`).join('')}</select></label><label>Encoder prescaler (PSC)<input id="stm-encoder-psc" type="number" min="0" max="65535" value="${draft.encoderPSC}"></label><p class="support-note">PA0 → Encoder A ve PA1 → Encoder B görevlerini birlikte seçin. Sayaç fiziksel giriş kenarlarından ilerler; PSC + 1 kenarı böler. Dijital filtre ve alternatif pin/remap register üzerinden ayarlanabilir.</p><hr><label>ADC1 çalışma modu<select id="stm-adc-mode">${[['prepare','Tek kanal hazırlığı'],['scan','Tarama · tek dizi'],['continuous','Tarama · sürekli'],['dma','DMA · sürekli dairesel SRAM tamponu']].map(([v,t])=>`<option value="${v}" ${draft.adcMode===v?'selected':''}>${t}</option>`).join('')}</select></label><label>ADC1 çözünürlük<select id="stm-adc-bits">${(b.cpu==='cortex-m4f'?[12,10,8,6]:[12]).map(n=>`<option ${draft.adcBits===n?'selected':''}>${n}</option>`).join('')}</select></label><label>ADC1 veri hizası<select id="stm-adc-left"><option value="0" ${!draft.adcLeft?'selected':''}>Sağ</option><option value="1" ${draft.adcLeft?'selected':''}>Sol</option></select></label><label>ADC1 EOC<select id="stm-adc-each"><option value="0" ${!draft.adcEach?'selected':''}>Dizi sonunda</option>${b.cpu==='cortex-m4f'?`<option value="1" ${draft.adcEach?'selected':''}>Her kanalda · overrun kontrolü</option>`:''}</select></label><label>ADC1 kanal sırası<input id="stm-adc-order" value="${esc(draft.adcOrder.join(', '))}" placeholder="PB0, PA1, PA4"></label><p class="support-note">Önce pin görevlerinden ADC1 kanallarını seçin. Boş sıra seçili kanalları pin numarasına göre kullanır; en fazla16 rank, tekrar eden kanal mümkündür. DMA seçimi12bit/sağ hizalama gerektirir; cf_adc_dma_values[] SRAM tamponuna sürekli aktarır. EXTI için listelenen IRQHandler içinde cf_exti_clear(pin) çağrılmalıdır. Tek kanal hazırlığı taramayı başlatmaz; tarama seçimleri main öncesinde başlar. main.c ayarları değiştirebilir. Sürekli ölçümü cf_adc_stop() durdurur.</p></section></div><div class="stm-code-section"><div><strong>Üretilecek C kodu</strong><span>cf_board_config.c / .h</span></div><pre id="stm-pin-code"></pre></div><p id="stm-config-error" role="status"></p><p class="support-note">GPIO ve yazılım I²C/SPI seçimleri gerçek C kodu üretir; saatler kurulduktan sonra, main öncesinde çalışır. main.c bu ayarları sonradan değiştirebilir. USART1/2 7E/O, 8N/E/O ve 9N / 0.5-2 stop pin iletişimi, ADC1 regular tarama / sürekli örnekleme (F10312bit; F4 12/10/8/6bit), TIM2 PWM1 / giriş yakalama / encoder ve SPI1 mode 0..3 / 8-16 bit / MSB-LSB master ve I²C1 7-bit master çalışır. Ayarlar yalnız bu projede saklanır; Uygula öncesi taslaktır. SPI1 PA4 NSS master çıkışı desteklenir. Kartta bulunan ek TIM/SPI/I²C/USART birimleri bağımsız register ve IRQ modeliyle çalışır. Ek SPI başlangıcı APB/64, I²C 100 kHz ve USART 9600 baud üretir; main.c değiştirebilir. Plan etiketi kalan eşlemeleri belirtir.</p><div class="dialog-actions"><button id="stm-pin-apply" class="primary">Uygula ve C kodunu üret</button></div></div>`);
 $('dialog').classList.add('stm-config-dialog');$('stm-internal-vbat').disabled=b.cpu!=='cortex-m4f';if(!b.gpio.includes('PA2')||!b.gpio.includes('PA3'))for(const id of ['stm-u2-sampling','stm-u2-bits','stm-u2-parity','stm-u2-stops','stm-u2-baud'])$(id).disabled=true;
 function saveActive(){draft.boot0=$('stm-boot0').checked;draft.boot1=$('stm-boot1').checked;draft.internalTemperature=Number($('stm-internal-temperature').value);draft.internalVBAT=Number($('stm-internal-vbat').value);if(!$('stm-pin-function').disabled)draft.pins[selected]={function:$('stm-pin-function').value,label:$('stm-pin-label').value.trim(),initial:+$('stm-pin-initial').value,...($('stm-pin-function').value.startsWith('exti_')?{extiPull:+$('stm-exti-pull').value}:{}),...($('stm-pin-function').value.startsWith('hw_TIM2_CH')?{pwmHz:+$('stm-pwm-hz').value,pwmDuty:+$('stm-pwm-duty').value}:$('stm-pin-function').value.startsWith('hw_TIM2_IC')?{captureHz:+$('stm-capture-hz').value,captureEdge:+$('stm-capture-edge').value,captureDivider:+$('stm-capture-divider').value}:{})};draft.encoderMode=+$('stm-encoder-mode').value;draft.encoderARR=+$('stm-encoder-arr').value;draft.encoderInvert=+$('stm-encoder-invert').value;draft.encoderPSC=+$('stm-encoder-psc').value;draft.rtcSource=+$('stm-rtc-source').value;draft.uart={enabled:$('stm-uart-on').checked,baud:+$('stm-uart-baud').value};draft.i2cHz=+$('stm-i2c-hz').value;draft.spiHz=+$('stm-spi-hz').value;draft.usart1Baud=+$('stm-usart1-baud').value;for(const n of [1,2]){draft['usart'+n+'Oversampling']=+$('stm-u'+n+'-sampling').value;draft['usart'+n+'Bits']=+$('stm-u'+n+'-bits').value;draft['usart'+n+'Parity']=+$('stm-u'+n+'-parity').value;draft['usart'+n+'Stops']=+$('stm-u'+n+'-stops').value;}draft.usart2Baud=+$('stm-u2-baud').value;draft.hwSpi1Hz=+$('stm-hw-spi-hz').value;draft.hwSpi1Mode=+$('stm-hw-spi-mode').value;draft.hwSpi1Bits=+$('stm-hw-spi-bits').value;draft.hwSpi1Lsb=$('stm-hw-spi-order').value==='1';draft.hwI2c1Hz=+$('stm-hw-i2c-hz').value;draft.adcMode=$('stm-adc-mode').value;draft.adcBits=+$('stm-adc-bits').value;draft.adcEach=$('stm-adc-each').value==='1';draft.adcLeft=$('stm-adc-left').value==='1';draft.adcOrder=$('stm-adc-order').value.trim()?$('stm-adc-order').value.toUpperCase().split(',').map(v=>v.trim()):[];}
 function preview(){let clock=b.hz/2;while(clock>draft.hwSpi1Hz&&clock>b.hz/256)clock/=2;$('stm-spi-clock').textContent='SPI1 · '+draft.hwSpi1Bits+'-bit / mode '+draft.hwSpi1Mode+' / '+(draft.hwSpi1Lsb?'LSB-first':'MSB-first')+' · Gerçek SCK: '+(clock/1000)+' kHz (PCLK2 / BR). '+(draft.pins.PA4?.function==='hw_SPI1_NSS'?'NSS: PA4 AF · SPE açıkken LOW.':'CS ayrı GPIO çıkışıdır.');try{const g=generatePinSources(draft,board);$('stm-pin-code').textContent=g.files[0].content+'\n'+g.files[1].content;$('stm-config-error').textContent='';}catch(e){$('stm-pin-code').textContent='Seçimleri tamamlayın: '+e.message;}}
 function renderList(){const search=$('stm-pin-search').value.toUpperCase();$('stm-pin-list').innerHTML=pins.filter(pin=>{const f=draft.pins[pin]?.function||'unused';return(pin+' '+f+' '+(draft.pins[pin]?.label||'')).toUpperCase().includes(search);}).map(pin=>{const f=draft.pins[pin]?.function||'unused',reserved=!b.gpio.includes(pin),name=pinFunctions(board,pin).find(v=>v.id===f)?.name||f;return`<button data-stm-pin="${pin}" class="stm-pin-row ${selected===pin?'selected':''} ${reserved?'reserved':isPlanned(pin,f)?'planned':f==='unused'?'unused':'assigned'}"><strong>${pin}</strong><small>${reserved?'Kart / debug için ayrılmış':esc(name)}</small></button>`;}).join('');for(const node of $('dialog-content').querySelectorAll('[data-stm-pin]')){const pin=node.dataset.stmPin,fn=draft.pins[pin]?.function||'unused';node.classList.toggle('assigned',fn!=='unused'&&!isPlanned(pin,fn));node.classList.toggle('planned',isPlanned(pin,fn));node.onclick=()=>{saveActive();selected=pin;renderEditor();renderList();preview();};}}
 function renderEditor(){const v=draft.pins[selected]||{function:'unused',label:'',initial:0},reserved=!b.gpio.includes(selected),functions=pinFunctions(board,selected);$('stm-pin-title').textContent=selected;$('stm-pin-aliases').textContent=b.pins.filter(p=>p.net===selected).map(p=>p.id).join(' · ');$('stm-pin-function').innerHTML='<optgroup label="Çalışan GPIO / ADC / TIM / SPI / I²C / USART">'+functions.filter(f=>f.status==='supported').map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')+'</optgroup><optgroup label="Datasheet · çevrebirim desteği bekliyor">'+functions.filter(f=>f.status==='planned').map(f=>`<option value="${f.id}">${esc(f.name)}${f.af!==null?' · AF'+f.af:f.remap?' · remap':''} · plan</option>`).join('')+'</optgroup>';$('stm-pin-function').value=v.function;$('stm-pin-label').value=v.label;$('stm-pin-initial').value=String(v.initial);$('stm-exti-pull').value=String(v.extiPull??2);$('stm-pwm-fields').hidden=!/^hw_TIM\d+_CH/.test(v.function);$('stm-capture-fields').hidden=!v.function.startsWith('hw_TIM2_IC');$('stm-capture-edge').value=String(v.captureEdge??0);$('stm-capture-divider').value=String(v.captureDivider??1);$('stm-capture-hz').value=String(v.captureHz??1000000);$('stm-pwm-hz').value=String(v.pwmHz??1000);$('stm-pwm-duty').value=String(v.pwmDuty??0);for(const id of ['stm-pin-function','stm-pin-label','stm-pin-initial'])$(id).disabled=reserved;$('stm-pin-initial').disabled=reserved||!['output','open_drain'].includes(v.function);$('stm-pin-support').textContent=reserved?'Bu pad varsayılan kart profili nedeniyle ayırılamaz. Kart köprüsü / SWD / kristal bilgilerini kontrol edin.':isPlanned(selected,v.function)?'Datasheet eşlemesi kaydedilir. Donanım çevrebirimi çalıştırılmaz; üretilen C içinde açıklama bulunur.':'Başlangıç kodu üretilecek. CF_ etiketi main.c içinde kullanılabilir.';}
 for(const n of [1,2])$('stm-u'+n+'-sampling').value=String(draft['usart'+n+'Oversampling']);renderEditor();renderList();preview();for(const key of ['bits','each','left','order'])$('stm-adc-'+key).disabled=draft.adcMode==='prepare';$('stm-pin-search').oninput=renderList;for(const id of ['stm-internal-temperature','stm-internal-vbat','stm-rtc-source','stm-exti-pull','stm-encoder-mode','stm-encoder-arr','stm-encoder-invert','stm-encoder-psc','stm-pin-function','stm-pin-label','stm-pin-initial','stm-pwm-hz','stm-pwm-duty','stm-capture-edge','stm-capture-divider','stm-capture-hz','stm-uart-on','stm-uart-baud','stm-usart1-baud','stm-u1-sampling','stm-u2-sampling','stm-u1-bits','stm-u1-parity','stm-u1-stops','stm-u2-bits','stm-u2-parity','stm-u2-stops','stm-u2-baud','stm-i2c-hz','stm-spi-hz','stm-hw-spi-hz','stm-hw-spi-mode','stm-hw-spi-bits','stm-hw-spi-order','stm-hw-i2c-hz','stm-adc-mode','stm-adc-bits','stm-adc-each','stm-adc-left','stm-adc-order'])$(id).onchange=()=>{saveActive();renderList();preview();for(const key of ['bits','each','left','order'])$('stm-adc-'+key).disabled=draft.adcMode==='prepare';if(id==='stm-pin-function'){$('stm-pin-initial').disabled=!['output','open_drain'].includes($('stm-pin-function').value);$('stm-pwm-fields').hidden=!/^hw_TIM\d+_CH/.test($('stm-pin-function').value);$('stm-capture-fields').hidden=!$('stm-pin-function').value.startsWith('hw_TIM2_IC');$('stm-pin-support').textContent=isPlanned(selected,$('stm-pin-function').value)?'Datasheet eşlemesi kaydedilir; çevrebirim simülasyonu açılmaz.':'Gerçek GPIO / bus / USART1 / ADC1 / TIM2 / SPI1 / I²C1 başlangıç kodu üretilecek.';}};$('stm-pin-apply').onclick=()=>{try{saveActive();apply(normalizePinConfig(draft,board));}catch(e){$('stm-config-error').textContent=e.message;}};
}
